function tiltProject(event){
 if(event.pointerType==='touch'||!motion)return;
 const el=event.currentTarget,box=el.getBoundingClientRect(),x=Math.max(0,Math.min(1,(event.clientX-box.left)/box.width)),y=Math.max(0,Math.min(1,(event.clientY-box.top)/box.height));
 el.style.setProperty('--rx',((.5-y)*7)+'deg');el.style.setProperty('--ry',((x-.5)*9)+'deg');el.style.setProperty('--mx',(x*100)+'%');el.style.setProperty('--my',(y*100)+'%');el.style.setProperty('--shine','.65');
}
function resetProject(event){const el=event.currentTarget;el.style.setProperty('--rx','0deg');el.style.setProperty('--ry','0deg');el.style.setProperty('--shine','0');}
function navigateBird(event,id){
 menu=false;if(!motion)return;
 const start=event.currentTarget.getBoundingClientRect(),target=document.getElementById(id)?.getBoundingClientRect();
 birdFlight={x:start.left+start.width/2,y:start.bottom+8,dx:window.innerWidth*.62-(start.left+start.width/2),dy:Math.max(150,Math.min(window.innerHeight*.7,target?.top||300))-(start.bottom+8)};
 laterEffect(()=>birdFlight=null,1150);
}
