n-out}.instagram:hover .camera-lens,.instagram:focus-visible .camera-lens{animation:camera-flash .8s ease-in-out}.medium:hover .medium-dot,.medium:focus-visible .medium-dot{transform-origin:center;animation:medium-pulse .7s ease-in-out}.medium .medium-dot:nth-child(2){animation-delay:.1s}.medium .medium-dot:nth-child(3){animation-delay:.2s}@keyframes social-bob{50%{transform:translateY(-3px)}}@keyframes github-nod{25%{transform:rotate(-10deg)}65%{transform:rotate(8deg)}}@keyframes linkedin-pop{50%{transform:scale(1.15)}}@keyframes camera-flash{50%{fill:#ffe0ec;filter:drop-shadow(0 0 5px #ffcee4)}}@keyframes medium-pulse{50%{transform:translateY(-3px);opacity:.6}}@media(prefers-reduced-motion:reduce){.social-emblem,.logo-social:hover svg,.logo-social:focus-visible svg,.instagram:hover .camera-lens,.instagram:focus-visible .camera-lens,.medium:hover .medium-dot,.medium:focus-visible .medium-dot{animation:none}.logo-socials .logo-social,.social-emblem,.social-spark,.social-arrow{transition:none}}

