.water-welcome{position:fixed;inset:0;z-index:1000;isolation:isolate;overflow:hidden;display:grid;place-items:center;background:radial-gradient(ellipse at 50% 40%,#143b62,#071426 80%);color:#f3fbff;font-family:Lexend,Arial,sans-serif;animation:water-exit .55s 2.65s ease-in both}.water-curtain{position:absolute;inset:0;display:flex;z-index:3;pointer-events:none}.water-curtain>span{flex:1;height:115%;background:linear-gradient(180deg,#afdfff,#62b7e2 45%,#3593c1cc 85%,#9cecff66);border-radius:0 0 45% 48%;box-shadow:inset 8px 0 16px #e7ffff25;transform:translateY(-110%);animation:waterfall-reveal 2.5s calc(var(--stream)*.045s) cubic-bezier(.45,0,.3,1) both}.water-drops{position:absolute;inset:0;pointer-events:none;opacity:.7}.water-drops i{position:absolute;left:var(--left);top:-5%;width:var(--size);height:calc(var(--size)*3);border-radius:50%;background:linear-gradient(#bcefff55,#7bd6f5);filter:drop-shadow(0 0 4px #82d6ee);animation:water-drop var(--speed) var(--delay) linear infinite}.welcome-center{position:relative;z-index:2;text-align:center;padding:30px;animation:welcome-rise .7s .65s both}.water-logo{position:relative;width:110px;height:110px;margin:0 auto 26px;border:1px solid #a4dff866;border-radius:28px;display:grid;place-items:center;background:linear-gradient(140deg,#bbeaff1c,#88baff09);box-shadow:0 0 50px #75cbf326,inset 0 0 20px #b8e8ff15}.water-logo>span{font-weight:900;font-size:51px;letter-spacing:-5px;color:#e9faff}.water-logo .logo-dot{font-size:36px;color:#8ceddc;letter-spacing:0}.water-logo>i{position:absolute;inset:-10px;border:1px solid #96daf944;border-radius:34px;animation:logo-ripple 2s .8s infinite}.water-logo>i:last-child{animation-delay:1.5s}.water-loading{font-size:10px;letter-spacing:4px;color:#8ad8f2;margin:0 0 17px}.welcome-center h1{font:500 clamp(25px,4vw,42px)/1.45 Lexend,Arial,sans-serif;margin:0;color:#e7f5ff}.welcome-center h1 em{font-style:normal;color:#a3ecf3}.water-progress{width:170px;height:3px;margin:28px auto 0;background:#c