/* Layered waterfall and liquid monogram reveal. */
.water-welcome{background:radial-gradient(ellipse at 50% 36%,#124e70 0,#09243c 42%,#030e1c 85%);animation:water-exit .75s 3.15s cubic-bezier(.4,0,.2,1) both}.water-curtain>span{background:linear-gradient(90deg,#d4fbff0d,#a1eafd99 15%,#5cbadfcc 36%,#c7f9ff99 50%,#4a98c588 70%,#b0eeff55 86%,transparent);border-radius:0 0 48% 44%;box-shadow:inset 4px 0 17px #d2fcff88,8px 0 30px #80d6f92b;animation:cinematic-fall 3.1s calc(var(--stream)*.045s) cubic-bezier(.4,0,.3,1) both}.water-curtain>span:nth-child(2n){background:linear-gradient(90deg,#4594bd55,#bcf2ff99,#65c4e699,#d9ffff88,#54a9d077);filter:blur(1px)}.water-atmosphere{position:absolute;inset:0;overflow:hidden;pointer-events:none}.water-atmosphere span{position:absolute;width:60vw;height:60vw;left:20%;top:-40%;background:radial-gradient(ellipse,#7ce8ef1a,transparent 66%);animation:water-caustic 5s ease-in-out infinite alternate}.water-atmosphere span:last-child{left:-20%;top:35%;background:radial-gradient(ellipse,#93bbff12,transparent 70%);animation-delay:-2s}.welcome-center{animation:welcome-rise 1s .8s cubic-bezier(.2,1,.3,1) both}.water-logo{width:180px;height:145px;background:linear-gradient(140deg,#c3f5ff08,#8abbf408);border:1px solid #a4dff82a;border-radius:32px;box-shadow:0 0 80px #75cbf326,inset 0 0 35px #b8e8ff09;margin-bottom:30px;transform:perspective(700px) rotateX(5deg)}.liquid-monogram{width:210px;height:140px;overflow:visible;filter:drop-shadow(0 0 12px #7ed8e966)}.monogram-fill{animation:monogram-rise 2.25s .7s cubic-bezier(.25,.1,.35,1) both}.logo-wave{animation:monogram-wave 1.8s linear infinite}.wave-b{animation-direction:reverse;animation-duration:2.4s}.monogram-star{position:absolute;right:-8px;top:0;color:#c5fff2;font-size:27px;animation:star-shimmer 1.8s .8s both}.water-logo>i{inset:-12px;border-radius:39px;border-color:#96daf933}.water-loading{color:#a6eefa;animation:loading-breathe 1.4s infinite}.welcome-center h1{font-size:clamp(26px,4vw,44px);letter-spacing:-1px;text-shadow:0 3px 22px #80d5ed20}.welcome-center h1 em{background:linear-gradient(90deg,#defaff,#8bddea,#c4c7ff);background-clip:text;-webkit-background-clip:text;color:transparent}.water-progress{width:190px;height:3px;margin-top:30px}.water-progress span{animation:welcome-progress 3s .5s both}.water-pool{height:210px;bottom:-85px;background:radial-gradient(ellipse,#5fcae933,transparent 70%);animation:pool-arrive 1.1s .8s both}.water-surface{position:absolute;inset:0;width:200%;height:100%;left:-50%;opacity:.4;animation:surface-drift 3s ease-in-out infinite alternate}.water-surface path{fill:#3681a944}.water-surface path:last-child{fill:#72c1d52b}.water-pool i{border-color:#94def566}.water-splash{position:absolute;left:50%;bottom:40px;pointer-events:none}.water-splash b{position:absolute;width:4px;height:9px;border-radius:50%;background:#b9edfa;box-shadow:0 0 8px #87d5ee;opacity:0;animation:welcome-splash 1.25s var(--splash-delay) both}.waterReveal{animation:portfolio-surface .85s cubic-bezier(.2,.8,.3,1) both}@keyframes cinematic-fall{0%{transform:translateY(-115%) scaleX(.7);opacity:.6}24%{transform:translateY(-5%) scaleX(1.02);opacity:1}39%{transform:translateY(0);opacity:1}67%{opacity:.9}100%{transform:translateY(115%) scaleX(1.15);opacity:0}}@keyframes monogram-rise{from{transform:translateY(155px)}to{transform:translateY(-22px)}}@keyframes monogram-wave{to{transform:translateX(120px)}}@keyframes star-shimmer{0%{opacity:0;transform:scale(.3) rotate(-40deg)}55%{opacity:1;transform:scale(1.2) rotate(8deg)}100%{opacity:1;transform:scale(1) rotate(0)}}@keyframes loading-breathe{50%{opacity:.5}}@keyframes water-caustic{to{transform:translate(15%,8%) scale(1.3)}}@keyframes pool-arrive{from{opacity:0;transform:translateY(50px)}to{opacity:1;transform:none}}@keyframes surface-drift{to{transform:translateX(10%) scaleY(.85)}}@keyframes welcome-splash{0%{opacity:0;transform:rotate(var(--angle)) translateX(0) scale(.3)}15%{opacity:.8}75%{opacity:.5}100%{opacity:0;transform:rotate(var(--angle)) translateX(var(--length)) scale(.2)}}@keyframes portfolio-surface{from{opacity:.5;filter:blur(5px);transform:translateY(12px)}to{opacity:1;filter:blur(0);transform:none}}@media(prefers-reduced-motion:reduce){.water-welcome,.waterReveal,.welcome-center,.monogram-fill,.logo-wave,.monogram-star,.water-loading{animation:none;transform:none}.monogram-fill{transform:translateY(-22px)}.water-atmosphere,.water-splash,.water-surface{display:none}}
